"""Islamiat (Ikhtiari) XII PDF89: pp.168–169 — Ibn Khaldun, Shah Waliullah; 4. scientific sciences: chemistry, physics, astronomy. Run: python class12_iski_page089.py"""
from class12_iski_common import BOOK, Builder, rec, P


def p89():
    b = Builder()
    P(b, [('"Plato and Aristotle cannot equal Ibn Khaldun, and all the political thinkers are not even worthy that they be mentioned together with a precious personality like Ibn Khaldun."', '”افلاطون اور ارسطو ابن خلدون کی برابری نہیں کر سکتے اور تمام سیاسی مفکرین تو اس قابل بھی نہیں کہ ان کا ابن خلدون جیسی مایہ ناز شخصیت کے ساتھ ذکر بھی کیا جائے۔“', '«افلاطون او ارسطو د ابن خلدون سیالي نشي کولی، او ټول سیاسي مفکرین خو دې وړ هم نه دي چې د ابن خلدون په څېر د ویاړ وړ شخصیت سره یاد شي.»'),
          ('Shah Waliullah (may Allah have mercy on him) too threw light on economic thought in his works, among which his well-known work Hujjat Allah al-Balighah also is, in which emphasis has been laid on the economic duties of the government. Besides this he has also written about the relation of economic disorder with morals. He has condemned the misuse of taxes and heavy taxes.', 'شاہ ولی اللہ رحمۃ اللہ علیہ نے بھی معاشی افکار پر اپنی تصانیف میں روشنی ڈالی جن میں ان کی معروف تصنیف حجۃ اللہ البالغہ بھی ہے جس میں حکومت کے معاشی فرائض پر زور دیا گیا ہے، اس کے علاوہ معاشی بگاڑ کا اخلاقیات سے تعلق کے بارے میں بھی لکھا ہے۔ ٹیکسوں کا غلط استعمال اور بھاری ٹیکسوں کی مذمت کی ہے۔', 'شاه ولي الله رحمه الله هم په خپلو تصنیفاتو کې پر اقتصادي افکارو رڼا اچولې، چې په هغو کې د هغه مشهور تصنیف «حجة الله البالغه» هم دی، چې په کې د حکومت پر اقتصادي دندو ټینګار شوی. سربېره پر دې یې د اقتصادي ګډوډۍ او اخلاقو د اړیکې په اړه هم لیکلي، او د مالیو ناسمه کارونه او درنې مالیې یې غندلې.')])
    b.h('4. Scientific sciences', '۴۔ سائنسی علوم', '۴. ساینسي علوم')
    b.p('Muslims accomplished invaluable services not only in religious, social and economic sciences, but also made great progress in scientific sciences. Among the scientific sciences are included chemistry, physics, psychology, astronomy, mathematics, agriculture and commerce etc. Because of these sciences the people of Europe are progressing by leaps and bounds today. Although all these sciences reached them through Muslim scientists, Muslims alone are their inventors and providers of their foundations.', 'نہ صرف دینی، معاشرتی، معاشی علوم میں مسلمانوں نے گرانقدر خدمات سرانجام دیں بلکہ سائنسی علوم میں بھی خوب ترقی کی۔ سائنسی علوم میں علم کیمیا، علم طبیعات، علم النفس، علم الفلکیات، علم الریاضی، علم الزراعۃ اور علم التجارہ وغیرہ شامل ہیں۔ ان علوم کی وجہ سے آج یورپ کے لوگ دن دگنی رات چوگنی ترقی کر رہے ہیں۔ حالانکہ یہ تمام علوم مسلمان سائنسدانوں کی وساطت سے ان تک پہنچے ہیں، مسلمان ہی ان کے موجد اور ان کی بنیادیں فراہم کرنے والے ہیں۔', 'مسلمانانو نه یوازې په دیني، ټولنیزو او اقتصادي علومو کې ارزښتناک خدمتونه سرته ورسول، بلکې په ساینسي علومو کې یې هم ښه پرمختګ وکړ. په ساینسي علومو کې کیمیا، فزیک، ارواپوهنه، نجوم، ریاضي، کرنه، سوداګري او نور شامل دي. د دې علومو له امله نن د اروپا خلک ورځ تر بلې ګړندی پرمختګ کوي. په داسې حال کې چې دا ټول علوم د مسلمانو ساینسپوهانو له لارې هغوی ته رسېدلي؛ مسلمانان یې موجدان او بنسټ برابروونکي دي.')
    b.h('Chemistry', 'علم کیمیا', 'کیمیا')
    P(b, [('This is the name of that science in which, by combining various elements through chemical methods, new compounds are formed, and the properties of these newly formed compounds are different from the earlier elements.', 'یہ اس علم کا نام ہے جس میں مختلف عناصر کو کیمیائی طریقوں سے ملانے سے نئے مرکبات بنتے ہیں اور ان نئے بننے والے مرکبات کی خصوصیات پہلے والے عناصر سے مختلف ہوتی ہیں۔', 'دا د هغه علم نوم دی چې په کې د بېلابېلو عناصرو په کیمیاوي لارو ګډولو نوي مرکبات جوړېږي، او د دې نویو جوړو شویو مرکباتو ځانګړنې له پخوانیو عناصرو توپیر لري.'),
          ('Jabir bin Hayyan was that first Muslim scientist who laid the foundation of modern chemistry, which is called (Chemistry) in English. Before this, the theory of ancient alchemy was that a recipe be used for making gold. The Greeks and other people spent most of their time in this, how to make gold. Jabir bin Hayyan showed the coming generations this path, that the science of chemistry is not merely making and searching for gold, but rather that it be used for the benefit of people.', 'جابر بن حیان وہ پہلا مسلمان سائنسدان تھا جس نے جدید کیمیا جسے انگریزی میں (Chemistry) کہا جاتا ہے، کی بنیاد رکھی۔ اس سے پہلے قدیم کیمیا کا نظریہ یہ تھا کہ سونا بنانے کے لیے کیا تراکیب استعمال کی جاتی ہیں۔ یونانی اور دیگر لوگوں نے زیادہ تر اپنا وقت اس میں لگایا کہ کیسے سونا بنایا جائے۔ جابر بن حیان نے آنے والی نسلوں کو یہ راستہ دکھایا کہ علم کیمیا صرف سونا بنانا اور تلاش کرنا نہیں ہے بلکہ اسے لوگوں کے فائدے کے لیے استعمال کیا جائے۔', 'جابر بن حیان هغه لومړنی مسلمان ساینسپوه و چې د عصري کیمیا — چې په انګلیسي کې ورته (Chemistry) وايي — بنسټ یې کېښود. له دې مخکې د لرغونې کیمیا نظریه دا وه چې د سرو زرو د جوړولو لپاره کوم ترکیبونه کارول کېږي. یونانیانو او نورو خپل ډېر وخت په دې کې تېر کړ چې سره زر څنګه جوړ شي. جابر بن حیان راتلونکو نسلونو ته دا لاره وښوده چې د کیمیا علم یوازې د سرو زرو جوړول او لټول نه دي، بلکې د خلکو د ګټې لپاره دې وکارول شي.'),
          ('Jabir bin Hayyan wrote approximately 70 treatises and many books on chemistry, among which Kitab al-Bayan, Kitab al-Tajrid, Kitab al-Asrar etc. are included. In his books Jabir wrote the methods and principles of making steel, dyeing leather, compounds of various metals, various acids, and making hair dyes. Besides this, his important achievement is the discovery of three mineral acids.', 'جابر بن حیان نے علم کیمیا پر تقریباً 70 رسائل اور بہت سی کتابیں لکھیں۔ جن میں کتاب البیان، کتاب التجرید، کتاب الاسرار وغیرہ شامل ہیں۔ جابر نے اپنی کتابوں میں فولاد بنانے، چمڑا رنگنے، مختلف دھاتوں کے مرکبات، مختلف تیزاب، اور بالوں کے خضاب بنانے کے طریقے اور اصول وغیرہ لکھے ہیں۔ ان کے علاوہ اس کا اہم کارنامہ تین معدنی تیزابوں کی دریافت ہے۔', 'جابر بن حیان پر کیمیا نږدې ۷۰ رسالې او ډېر کتابونه ولیکل، چې په هغو کې کتاب البیان، کتاب التجرید، کتاب الاسرار او نور شامل دي. جابر په خپلو کتابونو کې د فولادو جوړولو، د څرمنې رنګولو، د بېلابېلو فلزاتو مرکباتو، بېلابېلو تېزابونو او د وېښتو د خضاب جوړولو لارې او اصول لیکلي. سربېره پر دې د هغه مهمه کارنامه د درېیو معدني تېزابونو کشف دی.')])
    r1 = rec(b, 3, 168, 89, [168])
    t = Builder()
    t.p('Among the other names worth mentioning in chemistry are Muhammad Ibn Zakariya Razi, Abu al-Qasim Majriti and al-Kathi. Translations of their books have been made into Latin and other Western languages. Besides them, Ibn al-Wahshiyyah, Ya\'qub bin Ishaq al-Kindi and Ibn Sina etc. too are included among Muslim chemists.', 'علم کیمیا میں دوسرے قابلِ ذکر ناموں میں محمد ابن زکریا رازی، ابو القاسم مجریطی اور الکاثی ہیں۔ ان کی کتابوں کے ترجمے لاطینی اور دیگر مغربی زبانوں میں کیے گئے ہیں۔ اس کے علاوہ ابن الوحشیہ، یعقوب بن اسحاق الکندی اور ابن سینا وغیرہ بھی مسلمان کیمیا دانوں میں شامل ہیں۔', 'په کیمیا کې نور د یادونې وړ نومونه محمد ابن زکریا رازي، ابو القاسم مجریطي او الکاثي دي. د هغوی د کتابونو ژباړې په لاتیني او نورو لوېدیځو ژبو شوې. سربېره پر دې ابن الوحشیه، یعقوب بن اسحاق الکندي او ابن سینا او نور هم په مسلمانو کیمیاپوهانو کې شامل دي.')
    t.h('Physics', 'علم طبیعیات', 'فزیک')
    P(t, [('Physics is that science which in English is called (Physics). In it the study of mechanics, heat, light, magnetism, planets and space travel is included. Besides translating Greek books, Muslims invented many new concepts in this branch from which the whole world is benefiting till today. For example, the theories of Ibn al-Haytham, which are mostly about light and the eye. Among his famous works is "al-Manazir", in which complete information on "light" exists. Besides this he has many other books and works too. Bu Ali Sina studied natural bodies (matter), their motion and rest, and discovering many new things played his important role in physics. In the book "al-Mu\'tabar" of Abu al-Barakat al-Baghdadi, discussion on the topic of physics exists.', 'علم طبیعیات وہ علم ہے جسے انگریزی میں (Physics) کہا جاتا ہے۔ اس میں میکانیات، حرارت، روشنی، مقناطیسیت، سیاروں اور خلانوردی کا مطالعہ شامل ہے۔ یونانی کتابوں کے ترجمے کرنے کے علاوہ مسلمانوں نے اس شعبہ میں بہت سے نئے تصورات ایجاد کیے جن سے آج تک تمام دنیا مستفید ہو رہی ہے۔ مثلاً ابن الہیثم کے نظریات جو کہ زیادہ تر روشنی اور آنکھ کے بارے میں ہیں۔ اس کی مشہور تصانیف میں ”المناظر“ ہے۔ جس میں ”روشنی“ پر مکمل معلومات موجود ہیں۔ اس کے علاوہ بھی ان کی اور بہت سی کتب اور تصانیف ہیں۔ بوعلی سینا نے طبیعیات میں قدرتی اجسام (مادہ)، ان کی حرکت اور سکون کا مطالعہ کیا اور بہت سی نئی چیزیں دریافت کر کے علم طبیعیات میں اپنا اہم کردار ادا کیا۔ ابو البرکات البغدادی کی کتاب ”المعتبر“ میں طبیعات کے موضوع پر بحث موجود ہے۔', 'فزیک هغه علم دی چې په انګلیسي کې ورته (Physics) وايي. په دې کې د میخانیک، تودوخې، رڼا، مقناطیسیت، سیارو او فضايي سفر مطالعه شامله ده. د یوناني کتابونو له ژباړې سربېره مسلمانانو په دې څانګه کې ډېر نوي تصورات ایجاد کړل چې ټوله نړۍ ترې تر نن ګټه اخلي. لکه د ابن الهیثم نظریې چې ډېری یې د رڼا او سترګې په اړه دي. په مشهورو تصنیفاتو کې یې «المناظر» دی، چې په کې د «رڼا» په اړه بشپړ معلومات شته. سربېره پر دې یې نور ډېر کتابونه او تصنیفات هم شته. بوعلي سینا په فزیک کې د طبیعي اجسامو (مادې)، د هغو د حرکت او سکون مطالعه وکړه، او د ډېرو نویو شیانو په کشف یې په فزیک کې خپل مهم رول ولوباوه. د ابو البرکات البغدادي په کتاب «المعتبر» کې د فزیک پر موضوع بحث شته.'),
          ('The Chinese and Greeks were acquainted with magnetic attraction, but Muslim scientists for the first time made its practical benefits evident in the form of the compass, through which the art of navigation progressed. It was first mentioned in the Jawami\' of Muhammad al-\'Awfi. The relation of the eye and light and its properties, the invention of the camera, methods of weighing precious stones, the principles of the specific weight (Specific Gravity) of other liquids, methods of finding the degree of temperature, and basic concepts like the formation of the rainbow — these are the achievements and services of Muslim scientists alone.', 'چینی اور یونانی مقناطیسی کشش سے واقف تھے لیکن مسلمان سائنسدانوں نے پہلی دفعہ اس کے عملی فوائد قطب نما کی صورت میں ظاہر کیے۔ جس سے فنِ جہاز رانی میں ترقی ہوئی۔ محمد العوفی کی جوامع میں سب سے پہلے اس کا ذکر کیا گیا۔ آنکھ اور روشنی کا تعلق اور خصوصیات، کیمرہ کی ایجاد، قیمتی پتھروں کے وزن کرنے کے طریقے، اور دیگر مائعات کے وزنِ مخصوصہ (Specific Gravity) کے اصول، درجہ حرارت معلوم کرنے کے طریقے، اور قوسِ قزح کی تشکیل جیسے بنیادی تصورات مسلمان سائنسدانوں کے کارنامے و خدمات ہی ہیں۔', 'چینیان او یونانیان له مقناطیسي کشش سره بلد وو، خو مسلمانو ساینسپوهانو لومړی ځل یې عملي ګټې د قطب‌نما په بڼه ښکاره کړې، چې له امله یې د کښتۍ چلولو فن پرمختګ وکړ. لومړی ځل یې د محمد العوفي په «جوامع» کې یادونه وشوه. د سترګې او رڼا اړیکه او ځانګړنې، د کمرې اختراع، د قیمتي ډبرو د تللو لارې، د نورو مایعاتو د ځانګړي وزن (Specific Gravity) اصول، د تودوخې د درجې د معلومولو لارې، او د شنه‌زرغونې (قوس قزح) د جوړښت په څېر بنسټیز تصورات د مسلمانو ساینسپوهانو کارنامې او خدمتونه دي.')])
    t.h('Astronomy', 'علم فلکیات', 'نجوم (فلکیات)')
    t.p('It is also called \'Ilm al-Hay\'ah and (Astronomy). In astronomy Muslims accomplished prominent achievements. In this science the geometric structure of the universe is discussed, under which the distance of celestial bodies and the rules and regulations of their motions are laid down. For explaining these motions moving models (models) are made, which [are called] tables …', 'اس کو علم الہیئت اور (Astronomy) بھی کہا جاتا ہے۔ علم فلکیات میں مسلمانوں نے کارہائے نمایاں انجام دیئے۔ اس علم میں کائنات کی ہندسی ساخت سے بحث کی جاتی ہے۔ جس کے ماتحت اجرامِ فلکی کی دوری، حرکات کے قواعد و ضوابط منضبط کیے جاتے ہیں۔ ان حرکات کی توضیح کے لیے متحرک نمونے (models) بنائے جاتے ہیں۔ جنہیں جدول', 'دې ته علم الهیئت او (Astronomy) هم ویل کېږي. مسلمانانو په نجومو کې ښکاره کارنامې سرته ورسولې. په دې علم کې د کائنات له هندسي جوړښت بحث کېږي، چې تر هغه لاندې د آسماني اجسامو واټن او د حرکتونو قواعد او ضوابط ټاکل کېږي. د دې حرکتونو د وضاحت لپاره خوځنده نمونې (models) جوړېږي، چې جدول …')
    BOOK.save(89, [(3, r1), (3, rec(t, 3, 169, 89, [169]))], issues=[{'id': 'iski12-pdf089', 'unit': 3, 'printedPage': 168,
               'description': 'Robert Flint (d. 1910) quotation reproduced as printed in Urdu. Student handwriting at the astronomy heading on p.169 and a keyboard edge at the top of p.168 excluded. "طبیعات" / "طبیعیات" spellings kept as printed.'}])


if __name__ == '__main__':
    p89()
